const cmd = `node <<'NODE'
'use strict';
const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawn } = require('child_process');
const Redis = require('ioredis');

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bulk-hash-redis-'));
  const socket = path.join(dir, 'redis.sock');
  const server = spawn('/usr/bin/redis-server', [
    '--port', '0', '--unixsocket', socket, '--unixsocketperm', '700',
    '--save', '', '--appendonly', 'no', '--dir', dir
  ], { stdio: 'ignore' });
  const client = new Redis({ path: socket, lazyConnect: true, retryStrategy: times => times < 20 ? 50 : null });
  try {
    await client.connect();
    client.batch = client.pipeline.bind(client);
    const db = { client };
    require('./src/database/redis/hash')(db);

    assert.strictEqual(await db.incrObjectFieldByBulk([]), undefined);
    assert.strictEqual(await db.incrObjectFieldByBulk([
      ['new', { a: 1, b: -2 }],
      ['new', { a: 4 }],
      ['other', { c: 10 }],
    ]), undefined);
    assert.deepStrictEqual(await client.hgetall('new'), { a: '5', b: '-2' });
    assert.deepStrictEqual(await client.hgetall('other'), { c: '10' });

    await client.hmset('bad', { good: '1', broken: 'text' });
    db.objectCache.set('bad', { good: '1', broken: 'text' });
    db.objectCache.set('other', { c: '10' });
    await assert.rejects(db.incrObjectFieldByBulk([
      ['bad', { good: 5, broken: 1 }],
      ['other', { c: 2 }],
    ]));
    assert.deepStrictEqual(await client.hgetall('bad'), { good: '1', broken: 'text' });
    assert.strictEqual(await client.hget('other', 'c'), '12');
    assert.deepStrictEqual(db.objectCache.get('bad'), { good: '1', broken: 'text' });
    assert.strictEqual(db.objectCache.get('other'), undefined);

    await client.hmset('overflow', { first: '1', last: '9223372036854775807' });
    await assert.rejects(db.incrObjectFieldByBulk([['overflow', { first: 1, last: 1 }]]));
    assert.strictEqual(await client.hget('overflow', 'first'), '1');
    await Promise.all(Array.from({ length: 50 }, () => db.incrObjectFieldByBulk([['racing', { count: 1 }]])));
    assert.strictEqual(await client.hget('racing', 'count'), '50');
    console.log('isolated Redis bulk hash checks passed');
  } finally {
    client.disconnect();
    server.kill('SIGTERM');
    fs.rmSync(dir, { recursive: true, force: true });
  }
})().catch((err) => { console.error(err); process.exitCode = 1; });
NODE`;
const r=await tools.exec_command({cmd,workdir:"/app",max_output_tokens:6000,yield_time_ms:30000}); text(JSON.stringify(r));

